export default {"id": "06", "title": "两行字母，决定上下左右", "outline": [10, 8], "catalog": {"A": [3, 2], "B": [2, 3], "C": [2, 2], "D": [3, 1], "E": [2, 2]}, "scenes": [{"key": "intro-why", "chapter": 1, "title": "树给了遍历顺序，还能更直接吗？", "view": "intro-why06", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 3, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 18, "note": "序列对：两行字母直接记录每一对的相对位置", "say": "前两课的表示法都要\"按顺序走\"：切片用栈，B*-tree用遍历。序列对更直接：两行字母，每对模块的相对位置一次读完。水平约束给出x的下界，竖直约束给出y的下界，按拓扑序取最大值，坐标就出来了。", "start": 0, "delivery": "reading", "end": 18}, {"key": "intro-task", "chapter": 1, "title": "本课任务：建图、取最大、说清理由", "view": "intro-goal06", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 3, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 18, "note": "全部模块对分类→拓扑序→最长路径→关键约束", "say": "本课的任务是完整解码：把全部模块对按两行次序分类成水平或竖直约束，按拓扑序逐点取最大值算出最小可行坐标。学完你能解释为什么结果不重叠、为什么无环、哪条约束真正决定了坐标，也能构造一个不重叠却越界的编码。", "start": 18, "delivery": "reading", "end": 36}, {"key": "intro-preview", "chapter": 1, "title": "标准编码：还是那五块", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 3, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "ABCED / DABCE：D(0,3)，盒9×4=36", "say": "标准编码写作 ABCED / DABCE。解码结果是D在(0,3)、包围盒九乘四——D这次被B顶起来了。它和前一课的标准树不是同一份编码，结果也不同。", "start": 36, "delivery": "reading", "end": 49.5}, {"key": "notation", "chapter": 2, "title": "两行字母记录什么", "view": "sp-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "two", "note": "每一对模块：两行中的先后关系决定方向", "start": 49.5, "delivery": "voice", "end": 55.518}, {"key": "same-order", "chapter": 2, "title": "同序：水平约束，早者在左", "view": "pair-classify", "pair": "AB", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "same", "note": "A、B两行都先A后B → A在B左，x_B ≥ x_A + 3", "start": 55.518, "delivery": "voice", "end": 62.544}, {"key": "reverse-order", "chapter": 2, "title": "反序：竖直约束，早者在下", "view": "pair-classify", "pair": "AD", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "reverse", "note": "pos先A后D、neg后A先D → A在D下，y_D ≥ y_A + 2", "question": {"prompt": "若某资料约定\"反序=早者在上\"，只抄箭头会怎样？", "choices": ["y的不等式方向也要一起换，否则坐标全错", "只换箭头就够，不等式不变", "不影响任何结果"], "answer": 0, "replies": ["箭头和不等式必须一致：早者在上意味着y_j ≤ y_i，整套都要翻。", "不等式方向不同，只换箭头会算出矛盾或重叠。", "竖直约定决定整个解码，不能只改一半。"]}, "start": 62.544, "delivery": "voice", "end": 70.578}, {"key": "all-pairs", "chapter": 3, "title": "十对模块，全部分类", "view": "graph-view", "step": "graph", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "5选2共10对；每一对恰好进一个方向", "say": "五个模块共有十对。逐对检查两行次序：同序进水平约束，反序进竖直约束，每一对恰好进一个方向、不能遗漏。只连相邻的元素会漏掉远处的约束——D要越过的是下方全部模块。", "start": 70.578, "delivery": "reading", "end": 84.908}, {"key": "longest-path", "chapter": 3, "title": "坐标为什么取最大", "view": "graph-view", "step": "path", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "maximum", "note": "D必须越过A、B、C、E全部：y=max(2,3,2,2)=3", "say": "D的竖直前驱是A、B、C、E四个。只满足A会撞上B，只满足B又不够C的高度——所以要全部满足，也就是取最大。这就是最长路径：每个坐标是\"从起点到它的最长链长\"。", "start": 84.908, "delivery": "voice", "end": 93.926}, {"key": "predict-height", "chapter": 3, "title": "预测：D 最终停在哪？", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 3, 3, 1], ["E", 7, 0, 2, 2]], "voice": "predict", "note": "B的顶部比A高一格", "question": {"prompt": "D 的四个前驱给出的下界是：A顶2、B顶3、C顶2、E顶2。D 的 y 是多少？", "choices": ["3：取最大，B 是关键前驱", "2：跟 A 走", "8：把四个下界相加"], "answer": 0, "replies": ["同时满足四个下界就是取最大；B顶3最高。", "跟A走只满足一个约束，会与B重叠。", "相加把共享的路径重复计入，约束不是这样叠加的。"]}, "start": 93.926, "delivery": "voice", "end": 101.002}, {"key": "std-result", "chapter": 3, "title": "标准编码的完整结果", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 3, 3, 1], ["E", 7, 0, 2, 2]], "voice": "result", "note": "9×4=36；与前一课标准树的27不是同一份编码", "say": "标准编码解码完成：D在(0,3)，包围盒九乘四等于三十六。它合法装进10×8。提醒一句：这36和前一课标准树的27只是两份指定编码的结果，不能拿来给表示法排名。", "start": 101.002, "delivery": "voice", "end": 108.844}, {"key": "critical-chain", "chapter": 4, "title": "谁真正决定了坐标", "view": "critical-chain", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "D的y=3由B决定；改B的高度会沿链传播到D", "say": "四个前驱里只有B起作用，它是关键前驱。把B改高一点，D立刻跟着上移；把E去掉，D的y不变。最长路径的每一段都对应一条真正起作用的约束——这就是后面搜索里\"改一个尺寸会沿链传播\"的来源。", "start": 108.844, "delivery": "reading", "end": 125.174}, {"key": "acyclic", "chapter": 4, "title": "约束图为什么一定无环", "view": "acyclic-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "边总是从排列较早指向较晚：pos本身就是拓扑序", "say": "为什么约束图没有环？每条边都从\"两行中都较早\"指向\"较晚\"，所以按pos的顺序排下去，箭头永远指向前方——pos本身就是拓扑序。要出现环，得有某块\"既在前面又在后面\"，两个全排列做不到。有坐标就无环，无环才有最长路径。", "start": 125.174, "delivery": "reading", "end": 144.344}, {"key": "row-overflow", "chapter": 5, "title": "不重叠，但越过了外框", "view": "board-overflow06", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 7, 0, 3, 1], ["E", 10, 0, 2, 2]], "voice": "row", "note": "两行相同：全部同序 → 一行12宽，超出外框10", "say": "把两行写成完全一样：每一对都同序，全部是水平约束，五个模块排成一行，宽12。块与块互不重叠——序列对保证这一点——但E的右边缘到了12，外框只有10。解码合法和装进外框是两回事。", "start": 144.344, "delivery": "voice", "end": 152.522}, {"key": "fit-check", "chapter": 5, "title": "装进外框，交给Lab2", "view": "checks-cards06", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 12, "note": "不重叠由构造保证；越界由Lab2查；两道检查不能互相替代", "say": "序列对的解码由构造保证不重叠，这是它的优点；但它对外框只字不提。所以完整检查仍是两步：先看解码有没有报错，再用Lab2查包含性。5040棵树、14400个编码，都会有人忘了这一步。", "start": 152.522, "delivery": "reading", "end": 168.522}, {"key": "multi-encoding", "chapter": 6, "title": "同一张布局，三个编码", "view": "multi-encoding", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 3, 3, 2, 2], ["D", 0, 3, 3, 1], ["E", 5, 3, 2, 2]], "seconds": 15, "note": "ABDCE/DACEB、ABDCE/DCAEB、ABDCE/DCEAB解码完全一致", "say": "枚举全部14400个编码对：12966份不同布局，其中1234份有不止一个编码，最多的对应3个。比如这三份编码，解码结果逐块相同——C和E在第二行里的相对次序不影响任何约束。多对一是表示法的常态：搜索空间有冗余，比较算法时不能忽略。", "start": 168.522, "delivery": "reading", "end": 188.852}, {"key": "compare-reps", "chapter": 6, "title": "27 与 36 说明什么", "view": "compare-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 16, "note": "指定编码的结果≠表示法的能力；切片穷举最小25，B*-tree与序列对能到24", "say": "标准切片是27，标准B*-tree是27，标准序列对是36——这些只是\"指定编码的解码结果\"。要比较表示能力，得看编码空间能覆盖什么：这组固定五块、禁旋转的实例上，B*-tree 穷举5040棵树，最小包围盒24；序列对穷举14400个编码，最小也是24；切片却做不到——穷举26880份切片编码，最小只到25，一份24都没有。这两句证据要分开听：上一课结尾那张24布局确实一条第一刀都没有，所以它自己写不成切片树；但\"所有切片编码都到不了24\"不是从这一个布局推出来的，而是上面这次完备穷举的结果。单个反例说明不了其余两万多份编码，这个结论也只针对本实例。", "start": 188.852, "delivery": "reading", "end": 236.352}, {"key": "transfer-preview", "chapter": 7, "title": "交换一个排列：搜索的邻居", "view": "neighbor-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "交换pos中两个字母/同时交换两行：每次改完重新解码评分", "say": "序列对的编辑很自然：交换一个排列里的两个字母，或者同时交换两行里的两个字母。每改一次，重新解码、检查、评分。这正是下一课模拟退火要用的邻域——本课先把解码这一步做扎实，下节课才能专心研究\"接受还是拒绝\"。", "start": 236.352, "delivery": "reading", "end": 254.352}, {"key": "transfer", "chapter": 8, "title": "轮到你：建图、算坐标、构造反例", "view": "board", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 3, 3, 1], ["E", 7, 0, 2, 2]], "voice": "code", "note": "三项实验在下方Lab区；编码改完即可逐步解码", "start": 254.352, "delivery": "voice", "end": 261.426}], "chapters": ["两行字母，一张关系网", "方向约定与建图", "最长路径算坐标", "关键约束与无环", "不重叠不等于装得下", "表示多对一", "预览搜索的邻域", "轮到你建图"], "duration": 261.426, "readingSeconds": 201.16, "captions": [{"start": 0, "end": 6.0, "text": "前两课的表示法都要\"按顺序走\"：切片用栈，B*-tree用遍历。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 6.0, "end": 10.875, "text": "序列对更直接：两行字母，每对模块的相对位置一次读完。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 10.875, "end": 18.0, "text": "水平约束给出x的下界，竖直约束给出y的下界，按拓扑序取最大值，坐标就出来了。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 18, "end": 27.26732673267327, "text": "本课的任务是完整解码：把全部模块对按两行次序分类成水平或竖直约束，按拓扑序逐点取最大值算出最小可行坐标。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 27.26732673267327, "end": 36.0, "text": "学完你能解释为什么结果不重叠、为什么无环、哪条约束真正决定了坐标，也能构造一个不重叠却越界的编码。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 36, "end": 39.78, "text": "标准编码写作 ABCED / DABCE。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 39.78, "end": 45.36, "text": "解码结果是D在(0,3)、包围盒九乘四——D这次被B顶起来了。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 45.36, "end": 49.5, "text": "它和前一课的标准树不是同一份编码，结果也不同。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 49.5, "end": 55.518, "text": "序列对用两行字母记录每一对模块的相对位置。", "delivery": "voice", "sourceKey": "two", "words": [{"text": "序列", "start": 49.602083, "end": 49.992708}, {"text": "对用", "start": 50.00575, "end": 50.422416}, {"text": "两行", "start": 50.448458, "end": 50.839083}, {"text": "字母", "start": 50.852083, "end": 51.320833}, {"text": "记录", "start": 51.425, "end": 51.802625}, {"text": "每", "start": 51.828666, "end": 51.984916}, {"text": "一对", "start": 51.984916, "end": 52.245332}, {"text": "模块", "start": 52.258333, "end": 52.609916}, {"text": "的", "start": 52.609916, "end": 52.727124}, {"text": "相对", "start": 52.753125, "end": 53.117708}, {"text": "位置", "start": 53.13075, "end": 53.547416}]}, {"start": 55.518, "end": 62.544000000000004, "text": "A 和 B 在两个排列中顺序相同，所以 A 在 B 左边。", "delivery": "voice", "sourceKey": "same", "words": [{"text": "A", "start": 55.620083, "end": 55.958624}, {"text": "和", "start": 55.958625, "end": 56.153958}, {"text": "B", "start": 56.166958, "end": 56.479458}, {"text": "在", "start": 56.596666, "end": 56.804999}, {"text": "两", "start": 56.818, "end": 56.97425}, {"text": "个", "start": 56.97425, "end": 57.039375}, {"text": "排列", "start": 57.052375, "end": 57.312791}, {"text": "中", "start": 57.312791, "end": 57.560207}, {"text": "顺序", "start": 57.58625, "end": 57.937833}, {"text": "相同", "start": 57.950833, "end": 58.510749000000004}, {"text": "所以", "start": 58.83625000000001, "end": 59.38312500000001}, {"text": "A", "start": 59.500291000000004, "end": 59.773748999999995}, {"text": "在", "start": 59.77375000000001, "end": 59.956041}, {"text": "B", "start": 59.969041000000004, "end": 60.125291000000004}, {"text": "左边", "start": 60.138333, "end": 60.581041}]}, {"start": 62.544000000000004, "end": 70.578, "text": "A 在第一行先于 D，在第二行后于 D；按本课约定，A 在 D 下方。", "delivery": "voice", "sourceKey": "reverse", "words": [{"text": "A", "start": 62.646083000000004, "end": 62.91954100000001}, {"text": "在", "start": 62.91954100000001, "end": 63.127874000000006}, {"text": "第一", "start": 63.14087500000001, "end": 63.401291}, {"text": "行", "start": 63.401291, "end": 63.752874000000006}, {"text": "先", "start": 63.85704100000001, "end": 64.117457}, {"text": "于", "start": 64.11745800000001, "end": 64.27370800000001}, {"text": "D", "start": 64.27370800000001, "end": 64.49508300000001}, {"text": "在", "start": 64.755458, "end": 64.989833}, {"text": "第二", "start": 65.002875, "end": 65.26329100000001}, {"text": "行", "start": 65.26329100000001, "end": 65.445582}, {"text": "后", "start": 65.44558300000001, "end": 65.58883300000001}, {"text": "于", "start": 65.60183300000001, "end": 65.75808300000001}, {"text": "D", "start": 65.75808300000001, "end": 65.99245800000001}, {"text": "按", "start": 66.35704100000001, "end": 66.604416}, {"text": "本课", "start": 66.604416, "end": 66.916916}, {"text": "约定", "start": 66.92995800000001, "end": 67.359666}, {"text": "A", "start": 67.567958, "end": 67.854416}, {"text": "在", "start": 67.854416, "end": 68.02370700000002}, {"text": "D", "start": 68.036708, "end": 68.166916}, {"text": "下方", "start": 68.166916, "end": 68.60962400000001}]}, {"start": 70.578, "end": 72.19012500000001, "text": "五个模块共有十对。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 72.19012500000001, "end": 79.53425000000001, "text": "逐对检查两行次序：同序进水平约束，反序进竖直约束，每一对恰好进一个方向、不能遗漏。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 79.53425000000001, "end": 84.90800000000002, "text": "只连相邻的元素会漏掉远处的约束——D要越过的是下方全部模块。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 84.908, "end": 93.926, "text": "D 必须越过下方所有模块，而不只是 A，所以坐标要对所有前驱取最大。", "delivery": "voice", "sourceKey": "maximum", "words": [{"text": "D", "start": 85.010083, "end": 85.439791}, {"text": "必须", "start": 85.45279099999999, "end": 85.76529099999999}, {"text": "越过", "start": 85.778333, "end": 86.012708}, {"text": "下方", "start": 86.03875, "end": 86.455416}, {"text": "所有", "start": 86.481458, "end": 86.833041}, {"text": "模块", "start": 86.846041, "end": 87.262707}, {"text": "而", "start": 87.64029099999999, "end": 87.835624}, {"text": "不只", "start": 87.848625, "end": 88.135083}, {"text": "是", "start": 88.135083, "end": 88.447583}, {"text": "A", "start": 88.564791, "end": 88.981457}, {"text": "所以", "start": 89.241875, "end": 89.762708}, {"text": "坐标", "start": 89.866875, "end": 90.296583}, {"text": "要", "start": 90.309583, "end": 90.465833}, {"text": "对", "start": 90.465833, "end": 90.583041}, {"text": "所有", "start": 90.60904099999999, "end": 90.986666}, {"text": "前", "start": 90.99966599999999, "end": 91.221041}, {"text": "驱取", "start": 91.221041, "end": 91.507499}, {"text": "最大", "start": 91.5205, "end": 91.950208}]}, {"start": 93.926, "end": 101.002, "text": "其中 B 的顶部比 A 高一格；现在预测 D 的最终高度。", "delivery": "voice", "sourceKey": "predict", "words": [{"text": "其中", "start": 94.028083, "end": 94.444749}, {"text": "B", "start": 94.457791, "end": 94.587999}, {"text": "的", "start": 94.588, "end": 94.679166}, {"text": "顶部", "start": 94.692166, "end": 95.147916}, {"text": "比", "start": 95.265083, "end": 95.460416}, {"text": "A", "start": 95.473416, "end": 95.655707}, {"text": "高一格", "start": 95.655708, "end": 96.254666}, {"text": "现在", "start": 96.606208, "end": 97.022874}, {"text": "预测", "start": 97.035916, "end": 97.335374}, {"text": "D", "start": 97.335375, "end": 97.465583}, {"text": "的", "start": 97.465583, "end": 97.634874}, {"text": "最终", "start": 97.660916, "end": 98.025499}, {"text": "高度", "start": 98.0385, "end": 98.37704099999999}]}, {"start": 101.002, "end": 108.844, "text": "标准序列对得到九乘四的包围盒；它与前一课的标准树不是同一份编码。", "delivery": "voice", "sourceKey": "result", "words": [{"text": "标准", "start": 101.104083, "end": 101.53379099999998}, {"text": "序列", "start": 101.54679100000001, "end": 102.01554100000001}, {"text": "对", "start": 102.13274999999999, "end": 102.27599999999998}, {"text": "得到", "start": 102.28899999999999, "end": 102.54941599999998}, {"text": "九乘四", "start": 102.575458, "end": 103.09629099999998}, {"text": "的", "start": 103.09629099999998, "end": 103.17441599999998}, {"text": "包围", "start": 103.18741600000001, "end": 103.49991600000001}, {"text": "盒", "start": 103.49991600000001, "end": 103.825457}, {"text": "它", "start": 104.28116600000001, "end": 104.463457}, {"text": "与", "start": 104.463458, "end": 104.567624}, {"text": "前", "start": 104.59366600000001, "end": 104.762957}, {"text": "一", "start": 104.762958, "end": 104.841083}, {"text": "课", "start": 104.841083, "end": 104.932208}, {"text": "的", "start": 104.932208, "end": 104.997333}, {"text": "标准", "start": 105.010333, "end": 105.36191599999998}, {"text": "树", "start": 105.36191599999998, "end": 105.67441599999998}, {"text": "不是", "start": 105.791583, "end": 106.03899899999999}, {"text": "同", "start": 106.05199999999999, "end": 106.260333}, {"text": "一", "start": 106.260333, "end": 106.338458}, {"text": "份", "start": 106.338458, "end": 106.442624}, {"text": "编码", "start": 106.45566599999998, "end": 106.872332}]}, {"start": 108.844, "end": 112.2165, "text": "四个前驱里只有B起作用，它是关键前驱。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 112.2165, "end": 116.83149999999999, "text": "把B改高一点，D立刻跟着上移；把E去掉，D的y不变。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 116.83149999999999, "end": 125.17399999999999, "text": "最长路径的每一段都对应一条真正起作用的约束——这就是后面搜索里\"改一个尺寸会沿链传播\"的来源。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 125.17399999999999, "end": 126.93271559633027, "text": "为什么约束图没有环？", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 126.93271559633027, "end": 136.42977981651376, "text": "每条边都从\"两行中都较早\"指向\"较晚\"，所以按pos的顺序排下去，箭头永远指向前方——pos本身就是拓扑序。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 136.42977981651376, "end": 141.53005504587156, "text": "要出现环，得有某块\"既在前面又在后面\"，两个全排列做不到。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 141.53005504587156, "end": 144.344, "text": "有坐标就无环，无环才有最长路径。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 144.344, "end": 152.522, "text": "让两个排列完全相同，所有模块从左到右排开，仍然会超过外框。", "delivery": "voice", "sourceKey": "row", "words": [{"text": "让", "start": 144.446083, "end": 144.65441599999997}, {"text": "两", "start": 144.66745799999998, "end": 144.86274899999998}, {"text": "个", "start": 144.86274999999998, "end": 144.94087499999998}, {"text": "排列", "start": 144.953916, "end": 145.331541}, {"text": "完全", "start": 145.35754099999997, "end": 145.696082}, {"text": "相同", "start": 145.70912499999997, "end": 146.321125}, {"text": "所有", "start": 146.72474999999997, "end": 147.128416}, {"text": "模块", "start": 147.141416, "end": 147.610166}, {"text": "从", "start": 147.63620799999998, "end": 147.90962399999998}, {"text": "左", "start": 147.90962499999998, "end": 148.13099999999997}, {"text": "到", "start": 148.157041, "end": 148.274249}, {"text": "右", "start": 148.28724999999997, "end": 148.469541}, {"text": "排开", "start": 148.469541, "end": 148.95133199999998}, {"text": "仍然", "start": 149.26379099999997, "end": 149.69349899999997}, {"text": "会", "start": 149.70649999999998, "end": 149.82370799999998}, {"text": "超过", "start": 149.84974999999997, "end": 150.110166}, {"text": "外框", "start": 150.12316599999997, "end": 150.55287399999997}]}, {"start": 152.522, "end": 158.2108888888889, "text": "序列对的解码由构造保证不重叠，这是它的优点；但它对外框只字不提。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 158.2108888888889, "end": 163.89977777777779, "text": "所以完整检查仍是两步：先看解码有没有报错，再用Lab2查包含性。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 163.89977777777779, "end": 168.52200000000002, "text": "5040棵树、14400个编码，都会有人忘了这一步。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 168.522, "end": 176.93441379310343, "text": "枚举全部14400个编码对：12966份不同布局，其中1234份有不止一个编码，最多的对应3个。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 176.93441379310343, "end": 183.7695, "text": "比如这三份编码，解码结果逐块相同——C和E在第二行里的相对次序不影响任何约束。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 183.7695, "end": 188.852, "text": "多对一是表示法的常态：搜索空间有冗余，比较算法时不能忽略。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 188.85199999999998, "end": 196.85379211469532, "text": "标准切片是27，标准B*-tree是27，标准序列对是36——这些只是\"指定编码的解码结果\"。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 196.85379211469532, "end": 216.773146953405, "text": "要比较表示能力，得看编码空间能覆盖什么：这组固定五块、禁旋转的实例上，B*-tree 穷举5040棵树，最小包围盒24；序列对穷举14400个编码，最小也是24；切片却做不到——穷举26880份切片编码，最小只到25，一份24都没有。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 216.773146953405, "end": 231.41472401433688, "text": "这两句证据要分开听：上一课结尾那张24布局确实一条第一刀都没有，所以它自己写不成切片树；但\"所有切片编码都到不了24\"不是从这一个布局推出来的，而是上面这次完备穷举的结果。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 231.41472401433688, "end": 236.35199999999998, "text": "单个反例说明不了其余两万多份编码，这个结论也只针对本实例。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 236.35199999999998, "end": 243.05788235294116, "text": "序列对的编辑很自然：交换一个排列里的两个字母，或者同时交换两行里的两个字母。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 243.05788235294116, "end": 245.88141176470586, "text": "每改一次，重新解码、检查、评分。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 245.88141176470586, "end": 254.35199999999998, "text": "这正是下一课模拟退火要用的邻域——本课先把解码这一步做扎实，下节课才能专心研究\"接受还是拒绝\"。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 254.35199999999998, "end": 261.426, "text": "在实验里更改两个排列，再用 Python 写出最长路径更新。", "delivery": "voice", "sourceKey": "code", "words": [{"text": "在", "start": 254.45408299999997, "end": 254.66241599999995}, {"text": "实验", "start": 254.675458, "end": 255.05304099999995}, {"text": "里", "start": 255.05304099999995, "end": 255.339499}, {"text": "更改", "start": 255.456708, "end": 255.769208}, {"text": "两个", "start": 255.78220799999997, "end": 256.042624}, {"text": "排列", "start": 256.055666, "end": 256.49837399999996}, {"text": "再", "start": 256.73274999999995, "end": 256.915041}, {"text": "用", "start": 256.915041, "end": 257.09733199999994}, {"text": "Python", "start": 257.12337499999995, "end": 257.74837499999995}, {"text": "写出", "start": 257.852541, "end": 258.25620699999996}, {"text": "最", "start": 258.28220799999997, "end": 258.51658299999997}, {"text": "长", "start": 258.51658299999997, "end": 258.72491599999995}, {"text": "路径", "start": 258.737958, "end": 258.972333}, {"text": "更新", "start": 258.98533299999997, "end": 259.45408299999997}]}], "cuts": [{"scene": "notation", "sourceKey": "two", "sourceStart": 0.0, "sourceEnd": 6.018, "start": 49.5, "end": 55.518}, {"scene": "same-order", "sourceKey": "same", "sourceStart": 6.018, "sourceEnd": 13.044, "start": 55.518, "end": 62.544000000000004}, {"scene": "reverse-order", "sourceKey": "reverse", "sourceStart": 13.044, "sourceEnd": 21.078, "start": 62.544000000000004, "end": 70.578}, {"scene": "longest-path", "sourceKey": "maximum", "sourceStart": 21.078, "sourceEnd": 30.096, "start": 84.908, "end": 93.926}, {"scene": "predict-height", "sourceKey": "predict", "sourceStart": 30.096, "sourceEnd": 37.172, "start": 93.926, "end": 101.002}, {"scene": "std-result", "sourceKey": "result", "sourceStart": 37.172, "sourceEnd": 45.014, "start": 101.002, "end": 108.844}, {"scene": "row-overflow", "sourceKey": "row", "sourceStart": 45.014, "sourceEnd": 53.192, "start": 144.344, "end": 152.522}, {"scene": "transfer", "sourceKey": "code", "sourceStart": 53.192, "sourceEnd": 60.266, "start": 254.35199999999998, "end": 261.426}], "newSpeech": false, "audioSha256": "0b7e448f229afa302161c4bdb713700c08da06ac9a5b83b11442bc5901ccb04f", "sourceHashes": {"content/interactive06.mjs": "c7f6972e6438b2e5684ec9332aced32a6a3b77a6fc28601385c2127753f758cf", "dist/media/06/zh.m4a": "b25e64a88c2c1b092c7019cdfcfc5c2f882a70a63c8cc2c1e33aee551c7ba7a4", "dist/media/06/zh.json": "d9d4ad11e183555196e1a0141fc8b630cdcfd3707c7381866ad600e6276a33e2", "dist/assets/sp06.mjs": "374adc9bd3a09af7ae6d20e5e2e66e566ef6807914d18bf13dc5411b582a994b"}};
